@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* @nizivo/react/css/dialog.css (ARCHITECTURE.md §10.4, §12.1). Skeleton: the full visual pass lands later. */
@layer nz.components {
  /* The bare trigger, its own <button> (the part adds nz-hit-target only then): at least 24 x 24 px,
     the WCAG 2.2 2.5.8 minimum, so a short label or a lone glyph still meets it beside another
     target (M27). The rule also matches a composed Button or IconButton, which carry nz-hit-target
     themselves; at 32, 40 or 48 px it changes nothing there, and it floors a smaller custom height
     at 24 px. A consumer's own element through `render` carries no nz-hit-target and keeps its
     size. The coarse-pointer 44 px hit area is the nz.base .nz-hit-target rule. */
  .nz-dialog-trigger.nz-hit-target {
    min-inline-size: 1.5rem;
    min-block-size: 1.5rem;
  }

  /* never transformed and never clipping: it is the nested-portal container */
  .nz-dialog-positioner {
    position: fixed;
    inset: 0;
    z-index: var(--nz-z-overlay);
    display: grid;
    place-items: center;
    padding: var(--nz-space-8);
  }

  /* "the backdrop only fades" */
  .nz-dialog-backdrop {
    position: fixed;
    inset: 0;
    background: var(--nz-bg-scrim);
    transition: opacity var(--nz-duration-base) var(--nz-easing-enter);

    &[data-entering] {
      opacity: 0;
    }

    &[data-exiting] {
      opacity: 0;
      transition: opacity var(--nz-duration-fade) var(--nz-easing-exit);
    }
  }

  .nz-dialog-popup {
    --_nz-dialog-width: 30rem;

    position: relative; /* above the backdrop sibling */
    /* the width includes the forced-colours border, with or without a page reset (§8.1) */
    box-sizing: border-box;
    inline-size: min(var(--nz-dialog-width, var(--_nz-dialog-width)), 100%);
    max-block-size: calc(100dvh - 2 * var(--nz-space-8));
    display: flex;
    flex-direction: column;
    border-radius: var(--nz-dialog-radius, var(--nz-radius-2xl));
    background: var(--nz-dialog-bg, var(--nz-bg-surface-raised));
    box-shadow: var(--nz-elevation-4);
    transition:
      scale var(--nz-duration-spring) var(--nz-easing-spring),
      opacity var(--nz-duration-spring) var(--nz-easing-enter);

    &[data-entering] {
      opacity: 0;
      scale: var(--nz-scale-enter);
    }

    &[data-exiting] {
      opacity: 0;
      transition: opacity var(--nz-duration-fade) var(--nz-easing-exit);
    }

    &[data-size='sm'] {
      --_nz-dialog-width: 25rem; /* 400 px, provisional */
    }

    &[data-size='lg'] {
      --_nz-dialog-width: 40rem; /* 640 px, provisional */
    }
  }

  .nz-dialog-content {
    display: flex;
    flex-direction: column;
    min-block-size: 0;
    overflow: clip;
    border-radius: inherit;

    /* Focus lands on the dialog element itself (this one, role dialog, tabindex -1) when nothing
       inside takes it (a server-open dialog, or one opened from the keyboard): it is the container,
       so it shows no ring of its own, as the Menu and Select lists do not; Tab moves into it, where
       every control has the Nizivo ring. (Week 5 put this on .nz-dialog-popup, which never takes
       focus, so the browser's ring still showed: week 6 review.) */
    &:focus-visible {
      outline: none;
    }
  }

  /* A control placed straight in the popup can sit flush with its edge, where the clip above would
     cut an outside ring: its ring is drawn inside it instead, as in a scroller (§8.5
     data-focus-inset). The corner Close below is outside the clip and keeps its outside ring. */
  .nz-dialog-content
    > :not(.nz-dialog-close.nz-icon-button):is(:focus-visible, [data-focus-visible]) {
    outline-offset: calc(-1 * var(--nz-border-width-focus));
  }

  .nz-dialog-content > .nz-dialog-close.nz-icon-button {
    --_nz-icon-button-fg: var(--nz-icon-secondary);

    position: absolute;
    inset-block-start: calc(
      var(--nz-space-5) - (var(--nz-size-control-md) - var(--nz-size-icon-md)) / 2
    );
    inset-inline-end: calc(
      var(--nz-space-5) - (var(--nz-size-control-md) - var(--nz-size-icon-md)) / 2
    );
  }

  .nz-dialog-content:has(> .nz-dialog-close.nz-icon-button) > .nz-dialog-title {
    padding-inline-end: calc(var(--nz-space-5) + var(--nz-size-icon-md) + var(--nz-space-3));
  }

  .nz-dialog-title {
    margin: 0;
    padding: var(--nz-space-5) var(--nz-space-6) var(--nz-space-2);
    color: var(--nz-text-primary);
    font: var(--nz-font-heading-h3);
    letter-spacing: var(--nz-tracking-heading-h3);
  }

  .nz-dialog-description {
    margin: 0;
    padding: var(--nz-space-2) var(--nz-space-6);
    color: var(--nz-text-secondary);
    font: var(--nz-font-body-l);
  }

  /* the only scroller */
  .nz-dialog-body {
    overflow: auto;
    padding: var(--nz-space-2) var(--nz-space-6);
  }

  .nz-dialog-description:last-child,
  .nz-dialog-body:last-child {
    padding-block-end: var(--nz-space-6);
  }

  .nz-dialog-footer {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--nz-space-3);
    margin-block-start: var(--nz-space-4);
    padding: var(--nz-space-4) var(--nz-space-6);
    background: var(--nz-bg-subtle);
  }

  @media (forced-colors: active) {
    .nz-dialog-popup {
      border: 1px solid CanvasText;
    }
  }
}
